{"title": "CERT OPS — Signature Algorithm", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "padding": {"top": 0, "bottom": 0, "left": 0, "right": 0},
  "background": "#111111",
  "signals": [
    {
      "name": "sel", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? null : datum.k", "force": true}]
    },
    {
      "name": "_kf", "value": null,
      "on": [{"events": {"type": "click", "markname": "bg"}, "update": "datum.k === sel ? kibanaRemoveFilter({'match_phrase': {'certificate.signature_algorithm': datum.k}}) : kibanaAddFilter({'match_phrase': {'certificate.signature_algorithm': datum.k}})", "force": true}]
    }
  ],
  "data": [
    {
      "name": "raw",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {
          "by_sig": {"terms": {"field": "certificate.signature_algorithm", "size": 15, "order": {"_count": "desc"}}},
          "total":  {"value_count": {"field": "id"}}
        }}},
      "format": {"property": "aggregations.by_sig.buckets"},
      "transform": [
        {"type": "formula", "as": "k", "expr": "datum.key"},
        {"type": "formula", "as": "n", "expr": "datum.doc_count"},
        {"type": "formula", "as": "clr", "expr": "datum.key === 'MD5-RSA' ? '#ef5350' : datum.key === 'DSA-SHA1' || datum.key === 'SHA1-RSA' ? '#ef5350' : datum.key === 'ECDSA-SHA256' || datum.key === 'ECDSA-SHA384' || datum.key === 'ECDSA-SHA512' ? '#448aff' : datum.key === 'SHA256-RSA' || datum.key === 'SHA384-RSA' || datum.key === 'SHA512-RSA' ? '#ffa726' : datum.key === 'N/A' || datum.key === '0' ? '#555555' : '#00c853'"},
        {"type": "formula", "as": "bg",  "expr": "datum.key === 'MD5-RSA' ? '#ef535018' : datum.key === 'DSA-SHA1' || datum.key === 'SHA1-RSA' ? '#ef535018' : datum.key === 'ECDSA-SHA256' || datum.key === 'ECDSA-SHA384' || datum.key === 'ECDSA-SHA512' ? '#448aff18' : datum.key === 'SHA256-RSA' || datum.key === 'SHA384-RSA' || datum.key === 'SHA512-RSA' ? '#ffa72618' : '#55555518'"},
        {"type": "formula", "as": "tier","expr": "datum.key === 'MD5-RSA' ? 'BROKEN' : datum.key === 'DSA-SHA1' || datum.key === 'SHA1-RSA' ? 'LEGACY' : datum.key === 'ECDSA-SHA256' || datum.key === 'ECDSA-SHA384' || datum.key === 'ECDSA-SHA512' ? 'MODERN' : datum.key === 'SHA256-RSA' || datum.key === 'SHA384-RSA' || datum.key === 'SHA512-RSA' ? 'CLASSICAL' : datum.key === 'N/A' || datum.key === '0' ? 'UNKNOWN' : 'PQC READY'"},
        {"type": "formula", "as": "desc","expr": "datum.key === 'MD5-RSA' ? 'MD5 collision attacks are trivial — critically broken' : datum.key === 'SHA1-RSA' ? 'SHA-1 deprecated — browsers reject, fails compliance' : datum.key === 'DSA-SHA1' ? 'DSA with SHA-1 — both deprecated, remove immediately' : datum.key === 'SHA256-RSA' ? 'RSA with SHA-256 — dominant classical standard' : datum.key === 'SHA384-RSA' ? 'RSA with SHA-384 — stronger hash, still quantum-vulnerable' : datum.key === 'SHA512-RSA' ? 'RSA with SHA-512 — strongest classical RSA variant' : datum.key === 'ECDSA-SHA256' ? 'ECDSA with SHA-256 — modern, efficient, quantum-vulnerable' : datum.key === 'ECDSA-SHA384' ? 'ECDSA with SHA-384 — CNSA 1.0 approved, quantum-vulnerable' : 'Signature algorithm'"},
        {"type": "filter", "expr": "datum.k !== 'N/A' && datum.k !== '0'"},
        {"type": "collect", "sort": {"field": "n", "order": "descending"}},
        {"type": "window", "ops": ["rank"], "as": ["rnk"]},
        {"type": "formula", "as": "y",  "expr": "(datum.rnk - 1) * 66 + 52"}
      ]
    },
    {
      "name": "tot",
      "url": {"%context%": true, "%timefield%": "@timestamp", "index": "tychon-pqc-certificates*",
        "body": {"size": 0, "aggs": {"v": {"value_count": {"field": "id"}}}}},
      "format": {"property": "aggregations.v"},
      "transform": [{"type": "formula", "as": "n", "expr": "datum.value"}]
    },
    {
      "name": "mx",
      "source": "raw",
      "transform": [{"type": "aggregate", "ops": ["max"], "fields": ["n"], "as": ["v"]}]
    },
    {
      "name": "rows",
      "source": "raw",
      "transform": [
        {"type": "formula", "as": "tot", "expr": "length(data('tot'))>0 ? data('tot')[0].n : 1"},
        {"type": "formula", "as": "pct", "expr": "datum.tot > 0 ? datum.n / datum.tot : 0"}
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 18},
        "text": {"value": "SIGNATURE ALGORITHM"},
        "fill": {"value": "#cccccc"}, "fontSize": {"value": 10}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1.5}
      }}
    },
    {
      "type": "text",
      "encode": {"enter": {
        "x": {"value": 14}, "y": {"value": 34},
        "text": {"value": "HOW CERTIFICATES ARE SIGNED  —  click to filter"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "letterSpacing": {"value": 1}
      }}
    },
    {
      "type": "rule",
      "encode": {"enter": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"value": 42},
        "stroke": {"value": "#252525"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "rect", "name": "bg",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"signal": "width"}, "height": {"value": 60},
        "fill": {"signal": "datum.k===sel ? '#1c1c2e' : '#161616'"},
        "cursor": {"value": "pointer"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "y": {"field": "y"}, "width": {"value": 4}, "height": {"value": 60},
        "fill": {"field": "clr"}
      }}
    },
    {
      "type": "rule",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 0}, "x2": {"signal": "width"}, "y": {"signal": "datum.y + 59"},
        "stroke": {"value": "#222222"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 20"},
        "text": {"field": "k"}, "limit": {"signal": "width * 0.42"},
        "fill": {"value": "#e8e8e8"}, "fontSize": {"value": 13}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"value": 14}, "y": {"signal": "datum.y + 38"},
        "text": {"field": "desc"}, "limit": {"signal": "width * 0.55"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9}, "font": {"value": "monospace"}
      }}
    },
    {
      "type": "rect",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.60"}, "y": {"signal": "datum.y + 6"},
        "width": {"value": 68}, "height": {"value": 15}, "cornerRadius": {"value": 2},
        "fill": {"field": "bg"},
        "stroke": {"field": "clr"}, "strokeWidth": {"value": 1}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width * 0.60 + 34"}, "y": {"signal": "datum.y + 18"},
        "text": {"field": "tier"},
        "fill": {"field": "clr"},
        "fontSize": {"value": 8}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "center"}, "letterSpacing": {"value": 0.8}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 32"},
        "text": {"signal": "datum.n >= 1000 ? format(datum.n,'.3~s') : format(datum.n,',')"},
        "fill": {"signal": "datum.k===sel ? datum.clr : '#dddddd'"},
        "fontSize": {"value": 18}, "fontWeight": {"value": "bold"},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    },
    {
      "type": "text",
      "from": {"data": "rows"},
      "encode": {"update": {
        "x": {"signal": "width - 10"}, "y": {"signal": "datum.y + 47"},
        "text": {"signal": "format(datum.pct * 100, '.1f') + '%'"},
        "fill": {"value": "#555555"}, "fontSize": {"value": 9},
        "font": {"value": "monospace"}, "align": {"value": "right"}
      }}
    }
  ]
}
"}}
